#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t head;  /* write index */
    size_t tail;  /* read index */
    size_t size;  /* bytes currently stored */
};

/* =========================================================
 *  rb_create — allocate a ring buffer of given capacity
 *
 *  Returns NULL when capacity == 0 (invalid) or malloc fails.
 *  The internal array is zeroed so the buffer starts empty.
 * ========================================================= */
ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;

    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->head     = 0;
    rb->tail     = 0;
    rb->size     = 0;
    return rb;
}

/* =========================================================
 *  rb_destroy — free ring buffer (NULL-safe)
 * ========================================================= */
void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

/* =========================================================
 *  Helpers — compute wrapped index inside the internal store
 * ========================================================= */
static size_t wrap(const ringbuf_t *rb, size_t idx) { return idx % rb->capacity; }

/* How much space is available for writing? (= capacity - size) */
static size_t free_space(const ringbuf_t *rb) { return rb->capacity - rb->size; }

/* Number of contiguous bytes from index `idx` to the end of storage. */
static size_t span_from(const ringbuf_t *rb, size_t idx) { return rb->capacity - idx; }

/* =========================================================
 *  rb_write — append bytes (partial-write when full)
 *
 *  Returns number of bytes actually written.
 *  Writes as many contiguous blocks as needed, wrapping at
 *  the end of storage.
 * ========================================================= */
size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0 || rb_size(rb) == rb->capacity)
        return 0;

    size_t avail = free_space(rb);
    size_t n     = len < avail ? len : avail;  /* clamp to available space */

    /* First burst: head → end of storage or until data exhausted */
    size_t first = n < span_from(rb, rb->head) ? n : span_from(rb, rb->head);
    memcpy(rb->buf + wrap(rb, rb->head), data, first);
    rb->head = wrap(rb, rb->head + first);

    /* Second burst (if any): wraps around to start of storage */
    size_t rest = n - first;
    if (rest > 0) {
        memcpy(rb->buf, data + first, rest);
        rb->head =_wrap(rb, rb->head + rest);
    }

    rb->size += n;
    return n;
}

/* =========================================================
 *  rb_read — dequeue oldest bytes (NULL-safe)
 *
 *  Returns number of bytes actually read.
 * ========================================================= */
size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0 || rb->size == 0)
        return 0;

    size_t n = len < rb->size ? len : rb->size;  /* clamp to available */

    /* First burst: tail → end of storage or until data exhausted */
    size_t first = n < span_from(rb, rb->tail) ? n : span_from(rb, rb->tail);
    memcpy(out, rb->buf + wrap(rb, rb->tail), first);
    rb->tail = wrap(rb, rb->tail + first);

    /* Second burst (if any): wraps around to start of storage */
    size_t rest = n - first;
    if (rest > 0) {
        memcpy(out + first, rb->buf, rest);
        rb->tail = wrap(rb, rb->tail + rest);
    }

    rb->size -= n;
    return n;
}

/* =========================================================
 *  rb_peek — copy oldest bytes without removing them
 *
 *  Returns number of bytes actually copied.
 * ========================================================= */
size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0 || rb->size == 0)
        return 0;

    size_t n = len < rb->size ? len : rb->size;

    /* First burst */
    size_t first = n < span_from_const(rb, rb->tail) ? n : span_from_const(rb, rb->tail);
    memcpy(out, rb->buf + wrap(rb, rb->tail), first);

    /* Second burst (if any) */
    size_t rest = n - first;
    if (rest > 0) {
        memcpy(out + first, rb->buf, rest);
    }

    return n;
}

/* =========================================================
 *  rb_size / rb_capacity — query helpers (NULL-safe)
 * ========================================================= */
size_t rb_size(const ringbuf_t *rb)   { return rb ? rb->size     : 0; }
size_t rb_capacity(const ringbuf_t *rb) { return rb ? rb->capacity : 0; }

/* =========================================================
 *  rb_clear — discard all content (NULL-safe)
 * ========================================================= */
void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->size = 0;
}

#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t head;  /* next write index */
    size_t tail;  /* next read index  */
    size_t size;  /* bytes currently stored */
};

/* ---------- helpers ---------- */

static size_t wrap(const ringbuf_t *rb, size_t idx) { return idx % rb->capacity; }
static size_t free_space(const ringbuf_t *rb)        { return rb->capacity - rb->size; }
static size_t span_from(const ringbuf_t *rb, size_t idx) { return rb->capacity - idx; }

/* ---------- public API ---------- */

ringbuf_t *rb_create(size_t cap)  /* capacity must be > 0 */
{
    if (cap == 0)
        return NULL;

    ringbuf_t *rb = calloc(1, sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf   = calloc(cap, sizeof(uint8_t));
    if (!rb->buf) { free(rb); return NULL; }

    rb->capacity  = cap;     /* capacity > 0 already checked */
    rb->head      = 0;
    rb->tail      = 0;
    rb->size      = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)                  /* NULL is accepted (no-op) */
        return;
    free(rb->buf);
    free(rb);
}

size_t rb_size(const ringbuf_t *rb)      { return rb ? rb->size     : 0; }
size_t rb_capacity(const ringbuf_t *rb)   { return rb ? rb->capacity : 0; }
void rb_clear(ringbuf_t *rb)              { if (rb) { rb->head = 0; rb->tail = 0; rb->size = 0; } }

/* ---------- write / read / peek (shared layout) ---------- */

static size_t drain_one_burst(uint8_t *dst, const ringbuf_t *rb,
                              size_t max_n, int to_tail)  /* true for writes → head */
{
    size_t n = max_n < rb->size ? max_n : rb->size;
    size_t *idx_p = to_tail ? &rb->head : &rb->tail;

    size_t first = n < span_from( rb, *idx_p) ? n : span_from(rb, *idx_p);
    memcpy(dst, rb->buf + wrap(rb, *idx_p), first);
    *idx_p = wrap(rb, *idx_p + first);

    size_t rest = n - first;
    if (rest > 0) {
        memcpy(dst + first, rb->buf, rest);
        *idx_p = wrap(rb, *idx_p + rest);
    }
    return n;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0 || rb_size(rb) == rb->capacity)
        return 0;

    size_t avail = free_space(rb);
    size_t n     = len < avail ? len : avail;          /* clamp to space */

    size_t wrote = drain_one_burst((uint8_t *)data, rb, n, 1 /*→head*/);
    if (rb) rb->size += wrote;                         /* only here, after drain */
    return wrote;
}

#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *mem;          /* internal circular store (capacity bytes) */
    size_t   cap;          /* total capacity (> 0 when struct is alive)  */
    size_t   wpos;         /* next write position                       */
    size_t   rpos;         /* next read position                        */
    size_t   filled;       /* how many bytes are currently stored        */
};

/* ===== internal helpers (only valid on a live ringbuf_t) ====== */

static inline size_t wrap(ringbuf_t const *rb, size_t i)
{
    return i % rb->cap;
}

static inline size_t span_to_end(ringbuf_t const *rb, size_t pos)
{
    /* distance from pos to the end of ringbuf::mem */
    return rb->cap - pos;
}

/* ===== public API ====== */

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)          /* invalid: must be > 0                    */
        return NULL;

    ringbuf_t *rb = calloc(1, sizeof(*rb));
    if (!rb)
        return NULL;

    rb->mem  = calloc(capacity, 1);   /* calloc = zero-filled store         */
    if (!rb->mem) { free(rb); return NULL; }

    rb->cap   = capacity;
    rb->wpos  = 0;
    rb->rpos  = 0;
    rb->filled = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (rb == NULL)           /* spec: rb_destroy(NULL) is safe         */
        return;
    free(rb->mem);
    free(rb);
}

size_t rb_size(ringbuf_t const *rb)      { return rb ? rb->filled : 0; }
size_t rb_capacity(ringbuf_t const *rb)   { return rb ? rb->cap    : 0; }
void rb_clear(ringbuf_t *rb)              { if (rb) { rb->wpos = rb->rpos = rb->filled = 0; } }

/* ---------- write data into the ring buffer ---------- */
/*
 * Returns number of bytes actually written.  When full returns 0;
 * when only part fits, writes that part and returns the count.
 */
size_t rb_write(ringbuf_t *rb, uint8_t const *data, size_t len)
{
    if (!rb || !data || len == 0 || rb->filled == rb->cap)
        return 0;

    /* how many bytes can actually be stored right now */
    size_t avail = rb->cap - rb->filled;
    size_t n = len < avail ? len : avail;           /* clamp */

    /* Burst #1: consecutive bytes from wpos up to the end of mem */
    {
        size_t span = n < span_to_end(rb, rb->wpos) ? n : span_to_end(rb, rb->wpos);
        memmove(rb->mem + wrap(rb, rb->wpos), data, span);
        rb->wpos = wrap(rb, rb->wpos + span);
    }

    /* Burst #2: the remainder wraps around to address 0 */
    {
        size_t rem = n - (span_to_end(rb, rb->wpos) < n
                          ? span_to_end(rb, rb->wpos)
                          : n);   /* safe re-use after burst-1 mutation */
        if (rem > 0) {
            memmove(rb->mem, data + remaining, rem);
            rb->wpos = wrap(rb, rb->wpos + rem);
        }
    }

    rb->filled += n;
    return n;
}

