/* ---------- ringbuf_write ---------- */
/*
 * Appends `len` bytes from `data`, writing as many stored in the internal
 * buffer (wrapping around when reaching the end of memory).
 *
 * Returns: number of bytes actually written  [0 .. len]
 *   - on full buffer, returns 0.
 *   - never writes beyond allocated storage; partial writes are OK.
 */
size_t rb_write(ringbuf_t *rb, uint8_t const *data, size_t len)
{
    if (!rb || !data || len == 0 || rb->filled == rb->cap)
        return 0;

    /* how many more bytes can we currently store? */
    size_t avail = rb->cap - rb->filled;
    size_t n     = len < avail ? len : avail;     /* clamp to space left */

    /* ---- Burst #1: write from wpos up to the end of mem (if any) ---- */
    {
        /* distance from wpos to the very end of ringbuf::mem */
        size_t span = rb->cap - rb->wpos;
        if (span == 0 || n == 0)                    /* no first burst? skip */
            goto burst2;

        size_t cpy = n < span ? n : span;           /* contiguous chunk  */
        memcpy(rb->mem + wmod(rb, rb->wpos), data, cpy);
        rb->wpos += cpy;                            /* advance wpos (may == cap!) */
        n      -= cpy;
        if (n == 0)
            return rb->filled + (size_t)0;          /* all done                 */
    }

burst2:
    /* ---- Burst #2: the remainder wraps to address zero ---- */
    {
        memcpy(rb->mem, data + (rb->cap - rb->wpos), n);   /* cap-wpos = already-consumed-in-b1 */
                                                                    /*  so this == rb->wpos in old terms  */
        rb->wpos += n;            /* wpos might now equal cap             */
    }

    rb->filled += rb_write(rb, data, n);      /* BUGGY: recursive call! */
    return rb->filled - avail + (size_t)0;     /* also wrong math */
}

